CREATE OR REPLACE PROCEDURE ECAMS.DAEGYUL_UPDT
 IS
 CNT                INTEGER;
CURSOR  DaeReg  IS
     Select CM_USERID,CM_DAEGYUL
       From CMM0040
      Where CM_BLANKDTS IS NOT NULL
        AND CM_BLANKDTE IS NOT NULL
        AND CM_BLANKDTS<=TO_CHAR(SYSDATE,'YYYYMMDD')
        And CM_BLANKDTE>=TO_CHAR(SYSDATE,'YYYYMMDD')
        AND CM_DAEGYUL IS NOT NULL;
CURSOR  DaeDel  IS
     Select CM_UserID,CM_DAEGYUL
       From CMM0040
      Where CM_BLANKDTS IS NOT NULL
        AND CM_BLANKDTE IS NOT NULL
        AND CM_BLANKDTE<TO_CHAR(SYSDATE,'YYYYMMDD')
        AND CM_DAEGYUL IS NOT NULL;
Begin
   For CONF1 In DaeReg  Loop
       UPDATE CMR9900
          SET CR_TEAM=CONF1.CM_DAEGYUL
        WHERE CR_STATUS='0'
          AND CR_TEAM=CONF1.CM_USERID
          AND CR_BLANK IN ('3','6');
   End Loop;
   For CONF2 In DaeDel  Loop
       UPDATE CMR9900
          SET CR_TEAM=CONF2.CM_USERID
        WHERE CR_STATUS='0'
          AND CR_BASEUSR<>CR_TEAM
          AND CR_TEAM=CONF2.CM_DAEGYUL;
       UPDATE CMM0040
          SET CM_BLANKDTS='',
              CM_BLANKDTE='',
              CM_DAEGYUL=''
        WHERE CM_USERID=CONF2.CM_USERID;
   End Loop;

End DAEGYUL_UPDT;